Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/Array/Mem.lean"],{"text":"/-\nCopyright (c) 2022 Microsoft Corporation. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Leonardo de Moura, Joachim Breitner\n-/\nmodule\n\nprelude\npublic import Init.Data.Array.Basic\npublic import Init.WFTactics\nimport Init.Data.List.BasicAux\nimport Init.Data.Nat.Internal.Linear\nmeta import Init.MetaTypes\n\npublic section\n\nset_option linter.listVariables true -- Enforce naming conventions for `List`/`Array`/`Vector` variables.\nset_option linter.indexVariables true -- Enforce naming conventions for index variables.\n\nnamespace Array\n\ntheorem sizeOf_lt_of_mem [SizeOf α] {as : Array α} (h : a ∈ as) : sizeOf a < sizeOf as := by\n  cases as with | _ as\n  exact Nat.lt_trans (List.sizeOf_lt_of_mem h.val) (by simp +arith)\n\ntheorem sizeOf_get [SizeOf α] (as : Array α) (i : Nat) (h : i < as.size) : sizeOf as[i] < sizeOf as := by\n  cases as with | _ as\n  simpa using! Nat.lt_trans (List.sizeOf_get _ ⟨i, h⟩) (by simp +arith)\n\n@[simp] theorem sizeOf_getElem [SizeOf α] (as : Array α) (i : Nat) (h : i < as.size) :\n  sizeOf (as[i]'h) < sizeOf as := sizeOf_get _ _ h\n\n/-- This tactic, added to the `decreasing_trivial` toolbox, proves that\n`sizeOf arr[i] < sizeOf arr`, which is useful for well founded recursions\nover a nested inductive like `inductive T | mk : Array T → T`. -/\nmacro \"array_get_dec\" : tactic =>\n  `(tactic| first\n    -- subsumed by simp\n    -- | with_reducible apply sizeOf_get\n    -- | with_reducible apply sizeOf_getElem\n    | (with_reducible apply Nat.lt_of_lt_of_le (sizeOf_get ..)); simp +arith\n    | (with_reducible apply Nat.lt_of_lt_of_le (sizeOf_getElem ..)); simp +arith\n    )\n\nmacro_rules | `(tactic| decreasing_trivial) => `(tactic| array_get_dec)\n\n/-- This tactic, added to the `decreasing_trivial` toolbox, proves that `sizeOf a < sizeOf arr`\nprovided that `a ∈ arr` which is useful for well founded recursions over a nested inductive like\n`inductive T | mk : Array T → T`. -/\n-- NB: This is analogue to tactic `sizeOf_list_dec`\nmacro \"array_mem_dec\" : tactic =>\n  `(tactic| first\n    | with_reducible apply Array.sizeOf_lt_of_mem; assumption; done\n    | with_reducible\n        apply Nat.lt_of_lt_of_le (Array.sizeOf_lt_of_mem ?h)\n        case' h => assumption\n      simp +arith)\n\nmacro_rules | `(tactic| decreasing_trivial) => `(tactic| array_mem_dec)\n\nend Array\n","refs":[[21,8,21,24,"743d6cd1ca0d",true],[21,26,21,32,"03fe3de41e06",false],[21,42,21,47,"b78edb964ebc",false],[21,66,21,72,"218681b3ee23",false],[21,77,21,83,"218681b3ee23",false],[23,22,23,43,"fd268ec1b8c3",false],[23,61,23,66,"45ccb734be16",false],[25,20,25,26,"03fe3de41e06",false],[25,36,25,41,"b78edb964ebc",false],[25,50,25,53,"1a9353d78c15",false],[25,67,25,71,"e0ffe3f07488",false],[25,75,25,81,"218681b3ee23",false],[25,90,25,96,"218681b3ee23",false],[27,65,27,70,"45ccb734be16",false],[29,32,29,38,"03fe3de41e06",false],[29,48,29,53,"b78edb964ebc",false],[29,62,29,65,"1a9353d78c15",false],[29,79,29,83,"e0ffe3f07488",false],[30,2,30,8,"218681b3ee23",false],[30,21,30,27,"218681b3ee23",false],[35,24,35,30,"dfe60c6dc2a8",false],[50,24,50,30,"dfe60c6dc2a8",false]]});
